// ─── File: src/main/java/com/bank/messaging/demo/KafkaVsRabbitDemo.java ───
// Models Kafka (durable replayable log, multi-group) vs RabbitMQ (exchange routing,
// consume-once task queues).
package com.bank.messaging.demo;

import java.math.BigDecimal;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class KafkaVsRabbitDemo {

    private static final Logger log = Logger.getLogger("Messaging");
    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info("=== KAFKA: durable log, many groups read independently + replay ===");
        KafkaLog kafka = new KafkaLog();
        kafka.append("TXN-1", "SAV2001", new BigDecimal("20000"));
        kafka.append("TXN-2", "CUR3001", new BigDecimal("50000"));
        kafka.readAs("analytics-group");   // reads full stream
        kafka.readAs("fraud-group");       // reads the SAME stream independently
        kafka.replayAs("ledger-group");    // replays from offset 0 (data retained)

        log.info("=== RABBITMQ: exchange routes by key, consumed once, then gone ===");
        RabbitBroker rabbit = new RabbitBroker();
        rabbit.bind("loan.urgent", "urgent-queue");
        rabbit.bind("loan.normal", "normal-queue");
        rabbit.publish("loan.urgent", new LoanTask("L-1", "SAV2001", "URGENT"));
        rabbit.publish("loan.normal", new LoanTask("L-2", "CUR3001", "NORMAL"));
        rabbit.worker("urgent-queue").consumeOne();   // one worker, one message
        rabbit.worker("normal-queue").consumeOne();
        rabbit.worker("urgent-queue").consumeOne();    // already acked → empty
    }
}

// ─── Would be in KafkaLog.java (append-only, retained, offset per group) ───
class KafkaLog {
    private static final Logger log = Logger.getLogger("Messaging");
    private final List<String> partition = new ArrayList<>();     // retained records
    void append(String txnId, String account, BigDecimal amount) {
        partition.add(txnId + "|" + account + "|" + amount);
        log.info(() -> "appended " + txnId + " at offset " + (partition.size() - 1));
    }
    void readAs(String group) {
        for (int off = 0; off < partition.size(); off++) {
            final int o = off; final String rec = partition.get(off);
            log.info(() -> group + " read offset " + o + " -> " + rec);
        }
    }
    void replayAs(String group) {
        log.warning(() -> group + " REPLAY from offset 0 (data still on disk)");
        readAs(group);
    }
}

// ─── Would be in LoanTask.java ───
class LoanTask {
    final String taskId; final String accountId; final String priority;
    LoanTask(String taskId, String accountId, String priority) {
        this.taskId = taskId; this.accountId = accountId; this.priority = priority;
    }
}

// ─── Would be in RabbitBroker.java (exchange → binding → queue; consume-once) ───
class RabbitBroker {
    private static final Logger log = Logger.getLogger("Messaging");
    private final Map<String, String> bindings = new LinkedHashMap<>();        // routingKey→queue
    private final Map<String, Deque<LoanTask>> queues = new LinkedHashMap<>();
    void bind(String routingKey, String queue) {
        bindings.put(routingKey, queue);
        queues.putIfAbsent(queue, new ArrayDeque<>());
        log.fine(() -> "bound " + routingKey + " -> " + queue);
    }
    void publish(String routingKey, LoanTask task) {
        String queue = bindings.get(routingKey);   // exchange routes by key
        queues.get(queue).addLast(task);
        log.info(() -> "exchange routed " + task.taskId + " key=" + routingKey + " -> " + queue);
    }
    QueueWorker worker(String queue) { return new QueueWorker(queue, queues.get(queue)); }
}

// ─── Would be in QueueWorker.java (one worker consumes one message, acks → gone) ───
class QueueWorker {
    private static final Logger log = Logger.getLogger("Messaging");
    private final String queue; private final Deque<LoanTask> q;
    QueueWorker(String queue, Deque<LoanTask> q) { this.queue = queue; this.q = q; }
    void consumeOne() {
        LoanTask t = q.pollFirst();
        if (t == null) { log.warning(() -> queue + " empty (messages already consumed)"); return; }
        log.info(() -> "worker on " + queue + " processed " + t.taskId
                + " priority=" + t.priority + " -> ack (removed)");
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
